        eq(members.status, "suspended"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
