      userId: tenant.userIds.viewer,
    });
  });

  // A suspended member keeps their role and their seat; reinstating lifts it.
  it("suspends and reinstates a member without changing role or seats", async () => {
    const tenant = await createTenant("member-suspend-roundtrip", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");
    const seatsBefore = await memberRepo.countActiveMembers(tenant.org.id);

    const suspended = await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended).toMatchObject({ status: "suspended", role: "viewer" });
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(seatsBefore);

    const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(reinstated).toMatchObject({ status: "active", role: "viewer" });
  });

  // Nobody suspends themselves, and an admin cannot reach up to an owner.
  it("refuses self-suspension and suspending a higher role, changing nothing", async () => {
    const tenant = await createTenant("member-suspend-refused", "growth");
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!owner) throw new Error("fixture owner missing");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow(/yourself/);

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow(/cannot suspend or reinstate/);

    const stored = await memberRepo.findMemberById(tenant.org.id, owner.id);
    expect(stored?.status).toBe("active");
  });

  // Removal is not suspension: a removed member cannot be reinstated.
  it("treats a removed member as not found for suspension", async () => {
    const tenant = await createTenant("member-suspend-removed", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    await expect(
      memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

